create or replace function public.business_rewards_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with c as(select ci.id,coalesce(ci.points_awarded,0) points_awarded from check_ins ci join locations l on l.id=ci.location_id where l.business_id=p_business_id and ci.checked_in_at between p_start and p_end),pts as(select pt.id,pt.points,pt.reference_id from point_transactions pt where pt.created_at between p_start and p_end and(pt.reason ilike '%check%' or pt.reference_id in(select id from c))) select jsonb_build_object('check_ins',(select count(*) from c),'points_awarded',(select coalesce(sum(points_awarded),0) from c),'reward_events',(select count(*) from pts),'reward_points',(select coalesce(sum(points),0) from pts)); $$;
create or replace function public.business_event_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with ev as(select id from business_events where business_id=p_business_id and event_date between p_start::date and p_end::date),rs as(select count(distinct er.user_id) n from event_rsvps er where er.event_id in(select id from ev)),ae as(select count(*) filter(where event_type='location_view') views,count(*) filter(where event_type='event_rsvp') tracked_rsvps from analytics_events where event_id in(select id from ev) and created_at between p_start and p_end) select jsonb_build_object('events',(select count(*) from ev),'rsvps',(select n from rs),'event_views',(select views from ae),'event_rsvps_tracked',(select tracked_rsvps from ae)); $$;
